                              setTableStatuses(prev => ({ ...prev, [selectedTable.id]: 'SAVED' }));
                            }
                            setCart([]);
                            setTableCarts(prev => ({ ...prev, [selectedTable.id]: [] }));
                            toast.success("Saved to Billing!");
                            setActiveTrayTab('Billing');
                          }}"

